body.script:
const load = () => {
        const pageId = document.querySelector('body').id.replace('page-', '');
        IOMm('configure', { st: 'at_w_atarboe', dn: 'data-c062efa4b8.arboe.at', cn: 'at', mh: 5 }); // Configure IOMm
        IOMm('pageview', { cp: window.location.pathname, co: pageId }); // Count pageview
}
const init = () => {
    if (IOMm) load();
    else setTimeout(() => init(), 1000);
}
setTimeout(() => init(), 200);
